INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N026-06','CN0219','W05S15','共享站实际与项目设计','表3.2-7、4.5-1（检索摘录，PDF复开超时）','旧环评URL复用。表3.2-7实际全厂849351t、727581t回用、121770t排放、85.6%；正文1–6月与表标题1–11月冲突，不猜。表4.5-1项目设计68009t/a、削减57808、排放10201；COD产生74.877、削减74.367、排环境0.510t/a；氨氮2.274/2.223/0.051；TP、TN环境量0.003/0.091。冷凝废液S-1/S-2及精馏废液S-3 182.86/120.39/126.75t/a委外危废；非污水产生量。6条50t/a线合计300t/a；1000m³/h除盐水系统是公用供水RO，与废水膜分开。','WEB_PRIMARY','正文/截图或索引摘录；非原件归档','2026-11-27');
