INSERT INTO assert026 SELECT count(*)=0 FROM pragma_foreign_key_check;
INSERT INTO assert026 SELECT count(*)=0 FROM process_diagram_evidence e JOIN process_diagrams d USING(diagram_id) JOIN wastewater w USING(water_id) WHERE e.evidence_id LIKE 'DE026-%' AND d.site_id<>w.site_id;
INSERT INTO assert026 SELECT count(*)=0 FROM process_diagrams d WHERE d.diagram_id LIKE 'D026-%' AND NOT EXISTS (SELECT 1 FROM site_sources s WHERE s.site_id=d.site_id AND s.source_id=d.source_id);
